th, td { text-align:left; padding:.3rem .5rem; border-bottom:1px solid var(--line); vertical-align:top; }
th { font-weight:600; }
code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size:.85em; }
button { font:inherit; padding:.25rem .7rem; border-radius:.3rem; border:1px solid var(--accent); background:var(--accent); color:var(--bg); cursor:pointer; }
button:disabled { opacity:.5; cursor:default; }
.bar { height:.5rem; background:var(--line); border-radius:.25rem; overflow:hidden; display:flex; }
.bar span { display:block; height:100%; }
.bar .resolved { background:var(--ok); } .bar .ready { background:var(--accent); } .bar .draft { background:var(--warn); }
